#!/bin/bash
# ============================================================
# update46.sh
# 修復「建立新 context」功能只做半套（純 mkdir，從未產生 FreeSwitch
# 真正認得的頂層 <context name="..."> 定義），導致建立出來的 context
# 是空殼，選了必定 Context not found / NO_ROUTE_DESTINATION。已確認
# 至少造成分機 1126 一次完全無法撥出的事故。
# 對應：changelog-details/20260811-dialplan-context-orphan-fix.md
#
# 修改檔案：routers/dialplan_routes.py（整份覆寫）
# ============================================================
set -e

cd "$(dirname "$0")"

TARGET="routers/dialplan_routes.py"

# --- 0. 自動歸檔：把非本次腳本的其他 updateN.sh 搬進固定資料夾 ---
ARCHIVE_DIR="updateN"
SELF="$(basename "$0")"

mkdir -p "$ARCHIVE_DIR"
for f in update*.sh; do
  [ "$f" = "$SELF" ] && continue
  [ -f "$f" ] || continue
  git mv "$f" "${ARCHIVE_DIR}/$f" 2>/dev/null || mv "$f" "${ARCHIVE_DIR}/$f"
done
git add update*.sh "$ARCHIVE_DIR"/ 2>/dev/null || true
if ! git diff --cached --quiet 2>/dev/null; then
  git commit -m "chore: 歸檔已執行的 updateN.sh 腳本"
fi

# --- 1. 前置驗證 ---
echo "[前置驗證] 確認 $TARGET 目前內容符合預期（尚未套用本次改動）..."

if [ ! -f "$TARGET" ]; then
  echo "❌ 找不到 $TARGET" >&2
  exit 1
fi

if grep -q "_context_has_definition" "$TARGET"; then
  echo "❌ 偵測到 $TARGET 已包含 _context_has_definition，本次改動可能已套用過，中止避免重複套用" >&2
  exit 1
fi

if ! grep -q '純 mkdir，不做任何 SIP Profile' "$TARGET"; then
  echo "❌ $TARGET 內容與預期的舊版不符（找不到比對錨點），請先確認檔案目前實際內容，不要假設等於文件記錄的版本" >&2
  exit 1
fi

echo "  ✓ 前置驗證通過"

# --- 2. 整份覆寫（base64 還原，避免 SSH heredoc 貼上內容被截斷/打亂）---
echo "[Step 1] 覆寫 $TARGET..."
cp "$TARGET" "${TARGET}.pre-update46.bak"

echo "" | base64 -d > routers/dialplan_routes.py

if [ ! -s routers/dialplan_routes.py ]; then
  echo "❌ routers/dialplan_routes.py 覆寫後為空檔案，還原備份並中止" >&2
  cp routers/dialplan_routes.py.pre-update46.bak routers/dialplan_routes.py
  exit 1
fi

# --- 3. 語法驗證 ---
echo "[Step 2] Python 語法檢查..."
PY=python3
command -v /opt/myapp/venv/bin/python3 >/dev/null 2>&1 && PY=/opt/myapp/venv/bin/python3

$PY -c "import ast; ast.parse(open('routers/dialplan_routes.py').read())" \
  && echo "  ✓ 語法檢查通過" \
  || {
    echo "❌ 語法檢查失敗，還原備份" >&2
    cp routers/dialplan_routes.py.pre-update46.bak routers/dialplan_routes.py
    exit 1
  }

# --- 4. 清掉備份檔（確認語法過了才清）---
rm -f routers/dialplan_routes.py.pre-update46.bak

# --- 5. git commit ---
echo "[Step 3] git commit..."
git add routers/dialplan_routes.py
git status
git commit -m "fix: 建立新 context 功能只做半套（純 mkdir，缺頂層 <context name> 定義）導致空殼 context，補上頂層 XML 定義 + 立即 reload，list_contexts() 同步加上真偽校驗"

echo ""
echo "======================================================"
echo " ✓ update46.sh 執行完成"
echo ""
git log --oneline -1
echo ""
echo " ⚠️ 本次修改 routers/dialplan_routes.py，依慣例需要重啟服務讓改動生效："
echo "    systemctl restart fs-dashboard"
echo ""
echo " 驗證重點清單："
echo "  1. systemctl restart fs-dashboard 後 systemctl status fs-dashboard 確認正常啟動、無 500"
echo "  2. 確認既有 context 選單仍正常（default 應該還在，Dialplan 路由規則/自定義頁面正常運作）："
echo "     curl -s http://127.0.0.1:3000/api/dialplan/contexts -H \"Authorization: Bearer <token>\""
echo "  3. 確認 TC-ACSBC 這個既有空殼目前【不會】出現在上面的清單裡（這是預期行為，代表校驗生效）"
echo "  4. 到「自定義 Dialplan」頁面測試建立一個全新的測試 context（例如 test_ctx_$(date +%s)），確認："
echo "     - /etc/freeswitch/dialplan/<新名稱>/ 資料夾有建立"
echo "     - /etc/freeswitch/dialplan/<新名稱>.xml 也有建立，內容含 <context name=\"<新名稱>\">"
echo "     - GET /api/dialplan/contexts 立刻看得到這個新 context（不需要手動 reloadxml）"
echo "     - 測試完記得清掉：rm -rf /etc/freeswitch/dialplan/<新名稱> /etc/freeswitch/dialplan/<新名稱>.xml && fs_cli -x reloadxml"
echo "  5. 確認 default/public 不能被重複建立（應該回 400，訊息含「系統保留 context」）"
echo "  6. 確認 push 前 git status 乾淨、git log 看到本次 fix: commit"
echo "  7. push 由你自己手動執行"
echo "  8. 【下一步，另外處理】TC-ACSBC 這個既有空殼要手動補完頂層 XML 才會變成真正可用，"
echo "     不會因為這次部署自動修復，需要另外執行補完步驟"
echo "======================================================"
